/**
 * Bundled DCS reference data: countries, unit types, theatres (projection +
 * airfields with parking).
 *
 * Generated by `scripts/gen-reference-data.py` from pydcs, which exports these
 * tables from DCS itself. Loaded lazily — the airfield table is ~900 KB and most
 * sessions never need it.
 */
import { readFileSync } from "node:fs";
import { packagePath } from "../paths.js";

export interface Country {
  id: number;
  name: string;
  short: string;
}

export interface FlyingType {
  type: string;
  fuelMax: number | null;
  /** Dimensions in metres, used to pick a parking slot the aircraft fits. */
  width: number | null;
  length: number | null;
  height: number | null;
  chaff: number | null;
  flare: number | null;
  tasks: string[];
  defaultTask: string | null;
}

export interface NamedType {
  type: string;
  name: string;
  /** pydcs grouping, e.g. 'AirDefence', 'Armor', 'Fortification', 'Cargo'. */
  group?: string;
}

export interface StaticType extends NamedType {
  shape: string | null;
  /** The `category` field DCS writes on a static unit, e.g. 'Fortifications', 'Cargos'. */
  category: string;
  rate: number;
  canCargo: boolean;
}

export interface UnitTypes {
  plane: FlyingType[];
  helicopter: FlyingType[];
  vehicle: NamedType[];
  ship: NamedType[];
  static: StaticType[];
}

export type UnitCategory = keyof UnitTypes;

export interface Projection {
  centralMeridian: number;
  falseEasting: number;
  falseNorthing: number;
  scaleFactor: number;
}

/** [parking (crossroad index), parking_id (slot name), x, y, flags, width, length, height]. */
export type ParkingSlotTuple = [number, string, number, number, number, number, number, number];

export const SLOT_LARGE = 1;
export const SLOT_HELI = 2;
export const SLOT_AIRPLANES = 4;
export const SLOT_SHELTER = 8;

export interface Airport {
  id: number;
  name: string;
  x: number;
  y: number;
  slots: ParkingSlotTuple[];
}

export interface Theatre {
  projection: Projection;
  airports: Airport[];
}

function load<T>(file: string): T {
  return JSON.parse(readFileSync(packagePath("data", file), "utf8")) as T;
}

let countriesCache: Country[] | undefined;
let unitTypesCache: UnitTypes | undefined;
let theatresCache: Record<string, Theatre> | undefined;

export function countries(): Country[] {
  return (countriesCache ??= load<{ countries: Country[] }>("countries.json").countries);
}

export function unitTypes(): UnitTypes {
  if (!unitTypesCache) {
    const { _source: _s, ...rest } = load<UnitTypes & { _source: string }>("unit-types.json");
    rest.static = [...rest.static, ...HELIPORT_STATICS];
    unitTypesCache = rest;
  }
  return unitTypesCache;
}

export function theatres(): Record<string, Theatre> {
  return (theatresCache ??= load<{ theatres: Record<string, Theatre> }>("theatres.json").theatres);
}

const normalize = (s: string): string => s.toLowerCase().replace(/[\s_\-.]/g, "");

/** Common names people use for a theatre, mapped to the id DCS writes in the .miz. */
const THEATRE_ALIASES: Record<string, string> = {
  persiangulf: "PersianGulf",
  pg: "PersianGulf",
  sinai: "SinaiMap",
  marianas: "MarianaIslands",
  channel: "TheChannel",
  germany: "GermanyCW",
  coldwargermany: "GermanyCW",
  southatlantic: "Falklands",
};

/** Resolve a theatre name (case/spacing-insensitive, common aliases) to its DCS id. */
export function resolveTheatreName(name: string): string | undefined {
  const key = normalize(name);
  for (const id of Object.keys(theatres())) {
    if (normalize(id) === key) return id;
  }
  return THEATRE_ALIASES[key];
}

export function theatre(name: string): Theatre {
  const id = resolveTheatreName(name);
  const t = id ? theatres()[id] : undefined;
  if (!t) {
    throw new Error(
      `Unknown theatre '${name}'. Supported: ${Object.keys(theatres()).join(", ")}.`
    );
  }
  return t;
}

/** Find a country by name (case-insensitive) or short code. */
export function findCountry(name: string): Country | undefined {
  const key = normalize(name);
  return countries().find((c) => normalize(c.name) === key || normalize(c.short) === key);
}

export function findCountryById(id: number): Country | undefined {
  return countries().find((c) => c.id === id);
}

/**
 * Heliport statics. pydcs models these in `unit.py` rather than its generated
 * static catalogue, so they are listed here; dcs_miz_add_farp writes them.
 */
const HELIPORT_STATICS: StaticType[] = [
  { type: "FARP", name: "FARP (4 pads)", group: "Heliport", shape: "FARPS", category: "Heliports", rate: 0, canCargo: false },
  { type: "SINGLE_HELIPAD", name: "Single helipad", group: "Heliport", shape: "FARP", category: "Heliports", rate: 0, canCargo: false },
  { type: "Invisible FARP", name: "Invisible FARP", group: "Heliport", shape: "invisiblefarp", category: "Heliports", rate: 0, canCargo: false },
];

/** Find a unit type in any category (exact type id). */
export function findUnitType(type: string): { category: UnitCategory; entry: NamedType | FlyingType | StaticType } | undefined {
  const heliport = HELIPORT_STATICS.find((h) => h.type === type);
  if (heliport) return { category: "static", entry: heliport };
  const all = unitTypes();
  for (const category of Object.keys(all) as UnitCategory[]) {
    const entry = (all[category] as { type: string }[]).find((t) => t.type === type);
    if (entry) return { category, entry: entry as NamedType };
  }
  return undefined;
}

/** Suggest near matches for a type id that is not in the catalogue. */
export function suggestUnitTypes(type: string, limit = 5): string[] {
  const key = normalize(type);
  const all = unitTypes();
  const hits: string[] = [];
  for (const category of Object.keys(all) as UnitCategory[]) {
    for (const t of all[category] as { type: string; name?: string }[]) {
      if (normalize(t.type).includes(key) || (t.name && normalize(t.name).includes(key))) hits.push(t.type);
    }
  }
  return hits.slice(0, limit);
}

/** Find an airfield on a theatre by id or by name (case/spacing-insensitive, unique prefix ok). */
export function findAirport(theatreName: string, ref: string | number): Airport {
  const t = theatre(theatreName);
  if (typeof ref === "number" || /^\d+$/.test(String(ref))) {
    const id = Number(ref);
    const hit = t.airports.find((a) => a.id === id);
    if (!hit) throw new Error(`No airfield with id ${id} on ${theatreName}.`);
    return hit;
  }
  const key = normalize(String(ref));
  const exact = t.airports.filter((a) => normalize(a.name) === key);
  if (exact.length === 1) return exact[0];
  const partial = t.airports.filter((a) => normalize(a.name).includes(key));
  if (partial.length === 1) return partial[0];
  if (partial.length > 1) {
    throw new Error(
      `Airfield '${ref}' is ambiguous on ${theatreName}: ${partial.slice(0, 8).map((a) => a.name).join(", ")}.`
    );
  }
  throw new Error(`No airfield matching '${ref}' on ${theatreName}. Use dcs_list_airfields to see them.`);
}
